function registerAssistantsApi(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    HTTP.register!(router, "POST", path_prefix * "/threads/{thread_id}/runs/{run_id}/cancel", OpenAPI.Servers.middleware(impl, cancel_run_read, cancel_run_validate, cancel_run_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/assistants", OpenAPI.Servers.middleware(impl, create_assistant_read, create_assistant_validate, create_assistant_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/threads/{thread_id}/messages", OpenAPI.Servers.middleware(impl, create_message_read, create_message_validate, create_message_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/threads/{thread_id}/runs", OpenAPI.Servers.middleware(impl, create_run_read, create_run_validate, create_run_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/threads", OpenAPI.Servers.middleware(impl, create_thread_read, create_thread_validate, create_thread_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/threads/runs", OpenAPI.Servers.middleware(impl, create_thread_and_run_read, create_thread_and_run_validate, create_thread_and_run_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/assistants/{assistant_id}", OpenAPI.Servers.middleware(impl, delete_assistant_read, delete_assistant_validate, delete_assistant_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/threads/{thread_id}/messages/{message_id}", OpenAPI.Servers.middleware(impl, delete_message_read, delete_message_validate, delete_message_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/threads/{thread_id}", OpenAPI.Servers.middleware(impl, delete_thread_read, delete_thread_validate, delete_thread_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/assistants/{assistant_id}", OpenAPI.Servers.middleware(impl, get_assistant_read, get_assistant_validate, get_assistant_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/threads/{thread_id}/messages/{message_id}", OpenAPI.Servers.middleware(impl, get_message_read, get_message_validate, get_message_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/threads/{thread_id}/runs/{run_id}", OpenAPI.Servers.middleware(impl, get_run_read, get_run_validate, get_run_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/threads/{thread_id}/runs/{run_id}/steps/{step_id}", OpenAPI.Servers.middleware(impl, get_run_step_read, get_run_step_validate, get_run_step_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/threads/{thread_id}", OpenAPI.Servers.middleware(impl, get_thread_read, get_thread_validate, get_thread_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/assistants", OpenAPI.Servers.middleware(impl, list_assistants_read, list_assistants_validate, list_assistants_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/threads/{thread_id}/messages", OpenAPI.Servers.middleware(impl, list_messages_read, list_messages_validate, list_messages_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/threads/{thread_id}/runs/{run_id}/steps", OpenAPI.Servers.middleware(impl, list_run_steps_read, list_run_steps_validate, list_run_steps_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/threads/{thread_id}/runs", OpenAPI.Servers.middleware(impl, list_runs_read, list_runs_validate, list_runs_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/assistants/{assistant_id}", OpenAPI.Servers.middleware(impl, modify_assistant_read, modify_assistant_validate, modify_assistant_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/threads/{thread_id}/messages/{message_id}", OpenAPI.Servers.middleware(impl, modify_message_read, modify_message_validate, modify_message_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/threads/{thread_id}/runs/{run_id}", OpenAPI.Servers.middleware(impl, modify_run_read, modify_run_validate, modify_run_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/threads/{thread_id}", OpenAPI.Servers.middleware(impl, modify_thread_read, modify_thread_validate, modify_thread_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/threads/{thread_id}/runs/{run_id}/submit_tool_outputs", OpenAPI.Servers.middleware(impl, submit_tool_ouputs_to_run_read, submit_tool_ouputs_to_run_validate, submit_tool_ouputs_to_run_invoke; optional_middlewares...))
    return router
end
